package com.dy.artisan3d.ui.componentimport androidx.compose.foundation.isSystemInDarkThemeimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport dev.burnoo.compose.remembersetting.rememberBooleanSetting@Composablefun isDarkModeEnabled(): Boolean {    val savedDarkMode by rememberBooleanSetting(        key = "darkMode",        defaultValue = isSystemInDarkTheme()    )    return savedDarkMode}